// Лаб. 2, п. 2.2. Коннов, СДП-241 ИИ: статистика по оценкам студента
const PASS_AVERAGE = 6; // порог "зачёта" по среднему баллу

const input = msg.payload;
const scores = Array.isArray(input.scores) ? input.scores : [];

let sum = 0;
let count = 0;
let max = null;
const bad = []; // сюда складываем значения, которые не число

for (let i = 0; i < scores.length; i++) {
    const value = Number(scores[i]);
    if (Number.isNaN(value)) {
        bad.push(scores[i]);
        continue;
    }
    sum += value;
    count++;
    if (max === null || value > max) {
        max = value;
    }
}

let average = 0;
let verdict;
if (count === 0) {
    verdict = "нет данных";
} else {
    average = Math.round((sum / count) * 100) / 100;
    if (average >= PASS_AVERAGE) {
        verdict = "зачёт";
    } else {
        verdict = "не зачёт";
    }
}

const result = {
    student: input.name + " " + input.group,
    count: count,
    sum: sum,
    max: max,
    average: average,
    verdict: verdict,
    passed: verdict === "зачёт",
    ignored: bad
};

return { payload: result, topic: msg.topic };
